input.new_string:
function setChartPreviewNote(noteId, totalCount, previewCount) {
    var noteEl = noteId ? getEl(noteId) : null;
    if (!noteEl) {
        return;
    }
    if (totalCount > previewCount) {
        noteEl.textContent = "Hiển thị Top " + previewCount + " / " + totalCount + " — bấm phóng to để xem toàn bộ.";
        noteEl.className = "sad-dash-chart-note";
    } else {
        noteEl.textContent = "";
        noteEl.className = "sad-dash-chart-note d-none";
    }
}

function sliceTopCourses(rows, limit) {
    var sorted = (rows || []).slice(0);
    sorted.sort(function (a, b) {
        return getNum(b, "EnrolledCount", 0) - getNum(a, "EnrolledCount", 0);
    });
    return {
        items: limit && sorted.length > limit ? sorted.slice(0, limit) : sorted,
        total: sorted.length
    };
}

function buildCourseCategoriesAndSeries(items) {
    var categories = [];
    var enrolled = [];
    var i;
    for (i = 0; i < items.length; i++) {
        categories.push(getProp(items[i], "CourseName") || getProp(items[i], "CourseID") || "");
        enrolled.push(getNum(items[i], "EnrolledCount", 0));
    }
    return { categories: categories, enrolled: enrolled };
}

function buildCourseColumnOptions(categories, enrolled) {
    return {
        chart: {
            fontFamily: TITLE_FONT,
            foreColor: "#475569",
            toolbar: { show: false },
            width: "100%",
            type: "bar",
            height: 320
        },
        series: [
            { name: "Đã tuyển", data: enrolled }
        ],
        colors: [TEAL],
        plotOptions: {
            bar: {
                horizontal: false,
                borderRadius: 6,
                columnWidth: "55%",
                distributed: true
            }
        },
        dataLabels: {
            enabled: true,
            formatter: function (val) {
                return formatNumber(val);
            },
            style: { fontSize: "11px", fontWeight: 600 }
        },
        xaxis: {
            categories: categories,
            labels: {
                rotate: categories.length > 6 ? -35 : 0,
                trim: true,
                style: { fontSize: "11px" }
            }
        },
        yaxis: {
            labels: {
                formatter: function (val) {
                    return formatNumber(val);
                }
            }
        },
        legend: { show: false },
        grid: { borderColor: "#e2e8f0" },
        tooltip: {
            y: {
                formatter: function (val) {
                    return formatNumber(val) + " hồ sơ";
                }
            }
        }
    };
}

function buildCourseHorizontalOptions(categories, enrolled) {
    var height = Math.max(420, categories.length * 36 + 80);
    return {
        chart: {
            fontFamily: TITLE_FONT,
            foreColor: "#475569",
            toolbar: { show: false },
            width: "100%",
            type: "bar",
            height: height
        },
        series: [
            { name: "Đã tuyển", data: enrolled }
        ],
        colors: [TEAL],
        plotOptions: {
            bar: {
                horizontal: true,
                borderRadius: 4,
                barHeight: categories.length > 20 ? "70%" : "60%",
                distributed: true
            }
        },
        dataLabels: {
            enabled: true,
            formatter: function (val) {
                return formatNumber(val);
            },
            style: { fontSize: "11px", fontWeight: 600 }
        },
        xaxis: {
            categories: categories,
            labels: {
                formatter: function (val) {
                    return formatNumber(val);
                }
            }
        },
        legend: { show: false },
        grid: { borderColor: "#e2e8f0" },
        tooltip: {
            y: {
                formatter: function (val) {
                    return formatNumber(val) + " hồ sơ";
                }
            }
        }
    };
}

function setFullscreenButtonActive(isActive) {
    var btn = getEl("sadDashBtnFullscreenByCourse");
    if (!btn) {
        return;
    }
    if (isActive) {
        btn.classList.remove("sad-dash-fs-btn-inactive");
        btn.removeAttribute("aria-disabled");
    } else {
        btn.classList.add("sad-dash-fs-btn-inactive");
        btn.setAttribute("aria-disabled", "true");
    }
}

function openCourseFullscreen() {
    var overlay = getEl("sadDashFullscreenOverlay");
    var titleEl = getEl("sadDashFullscreenTitle");
    var chartWrap = getEl("sadDashFullscreenChartWrap");
    var options;
    if (!overlay || !fullscreenByCourse || typeof ApexCharts === "undefined") {
        return;
    }
    if (titleEl) {
        titleEl.textContent = fullscreenByCourse.title || "Đã tuyển theo khóa (toàn bộ)";
    }
    destroyChart("byCourseFullscreen");
    options = fullscreenByCourse.optionsBuilder();
    if (chartWrap && options && options.chart) {
        chartWrap.style.height = options.chart.height + "px";
    }
    chartInstances.byCourseFullscreen = new ApexCharts(getEl("sadDashChartByCourseFullscreen"), options);
    chartInstances.byCourseFullscreen.render();
    overlay.className = "sad-dash-fullscreen";
    document.body.style.overflow = "hidden";
}

function closeCourseFullscreen() {
    var overlay = getEl("sadDashFullscreenOverlay");
    var chartWrap = getEl("sadDashFullscreenChartWrap");
    if (!overlay) {
        return;
    }
    overlay.className = "sad-dash-fullscreen d-none";
    document.body.style.overflow = "";
    destroyChart("byCourseFullscreen");
    if (chartWrap) {
        chartWrap.style.height = "";
    }
}

function renderChartByCourse(rows) {
    destroyChart("byCourse");
    fullscreenByCourse = null;
    setFullscreenButtonActive(false);

    var sliced = sliceTopCourses(rows, TOP_COURSE_LIMIT);
    setChartPreviewNote("sadDashChartByCourseNote", sliced.total, TOP_COURSE_LIMIT);

    var isEmpty = !sliced.items.length || typeof ApexCharts === "undefined";
    setChartEmpty("sadDashChartByCourse", "sadDashChartByCourseEmpty", isEmpty);
    if (isEmpty) {
        return;
    }

    var preview = buildCourseCategoriesAndSeries(sliced.items);
    var options = buildCourseColumnOptions(preview.categories, preview.enrolled);
    chartInstances.byCourse = new ApexCharts(getEl("sadDashChartByCourse"), options);
    chartInstances.byCourse.render();

    fullscreenByCourse = {
        title: "Đã tuyển theo khóa (toàn bộ — " + sliced.total + " khóa)",
        optionsBuilder: function () {
            var all = sliceTopCourses(rows, 0);
            var full = buildCourseCategoriesAndSeries(all.items);
            return buildCourseHorizontalOptions(full.categories, full.enrolled);
        }
    };
    setFullscreenButtonActive(true);
}

