function bindEvents() {
    if (eventsBound) {
        return;
    }
    eventsBound = true;
    bindMultiSelectTriggers();
    bindMultiSelectEvents(getEl("sadCourseFilter"));
    bindMultiSelectEvents(getEl("sadSpecialBranchFilter"));

    var btnLoad = getEl("sadDashBtnLoad");
    var btnRefresh = getEl("sadDashBtnRefresh");
    var btnFs = getEl("sadDashBtnFullscreenByCourse");
    var btnCloseFs = getEl("sadDashBtnCloseFullscreen");
    if (btnLoad) {
        btnLoad.addEventListener("click", fetchDashboard);
    }
    if (btnRefresh) {
        btnRefresh.addEventListener("click", fetchDashboard);
    }
    if (btnFs) {
        btnFs.addEventListener("click", function () {
            if (btnFs.classList.contains("sad-dash-fs-btn-inactive")) {
                return;
            }
            openCourseFullscreen();
        });
    }
    if (btnCloseFs) {
        btnCloseFs.addEventListener("click", closeCourseFullscreen);
    }
    document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") {
            closeCourseFullscreen();
        }
    });
}

